create table if not exists public.client_invoice_charges(id uuid default gen_random_uuid(),tenant_id uuid,invoice_id uuid,source_type text,source_id uuid,source_number text,source_series text,reference_number text,issue_date date,description text,gross_amount numeric(14,2) default 0,discount_amount numeric(14,2) default 0,interest_amount numeric(14,2) default 0,ir_amount numeric(14,2) default 0,net_amount numeric(14,2) default 0,sort_order integer default 0,metadata jsonb default '{}'::jsonb,cancelled_at timestamp with time zone,created_at timestamp with time zone default now());
create table if not exists public.client_invoice_details(id uuid default gen_random_uuid(),tenant_id uuid,invoice_id uuid,charge_id uuid,source_type text,source_id uuid,emission_date date,document_label text,document_number text,ort_number text,destination text,remitter text,recipient text,weight_kg numeric(14,3),cargo_value numeric(14,2),displayed_freight_value numeric(14,2),notes text,metadata jsonb default '{}'::jsonb,sort_order integer default 0,created_at timestamp with time zone default now());
create table if not exists public.closing_report_charge_claims(id uuid default gen_random_uuid(),tenant_id uuid,report_id uuid,item_id uuid,fiscal_document_id uuid,attempt_id uuid,amount numeric(14,2),source_key text generated always as (((('delivery:'::text || (fiscal_document_id)::text) || ':'::text) || COALESCE((attempt_id)::text, 'original'::text))) stored,claimed_at timestamp with time zone default clock_timestamp(),claimed_by uuid,released_at timestamp with time zone,released_by uuid,release_reason text);
